using System.IO;using System.Numerics;using System.Text;using System.Text.Json;using System.Xml;using System.Xml.Linq;using System.Text.RegularExpressions;using FaceAssets;
namespace DanceStudio;
// All formats end in the existing Rig/Pose model. Quaternions are x,y,z,w;
// source coordinates stay Skyrim units, +Z up. Only the viewport converts Y/Z.
public static class SkeletonImport {
 public const int MaxBones=4096;public const int MaxBytes=64*1024*1024;
 public static string Filter=>UiText.T("skeletonFilter");
 public static Rig Read(byte[] bytes,string source){if(bytes.Length<2||bytes.Length>MaxBytes)throw new InvalidDataException(UiText.T("skeletonSize"));Rig rig;int start=bytes.AsSpan().StartsWith(new byte[]{239,187,191})?3:0;while(start<bytes.Length&&char.IsWhiteSpace((char)bytes[start]))start++;
  if(bytes.AsSpan().StartsWith(Encoding.ASCII.GetBytes("Gamebryo File Format"))){rig=ReadNif(source);}
  else if(bytes.Length>=8&&BitConverter.ToUInt32(bytes,0)==0x57e0e057&&BitConverter.ToUInt32(bytes,4)==0x10c0c010)rig=SkeletonPack.Read(bytes);
  else if((start<bytes.Length&&bytes[start]=='<')||bytes.AsSpan().StartsWith(new byte[]{255,254})||bytes.AsSpan().StartsWith(new byte[]{254,255}))rig=ReadXml(bytes);
  else if(start<bytes.Length&&bytes[start]=='{')rig=ReadJson(bytes);
  else throw new InvalidDataException(UiText.T("skeletonUnknown"));
  Validate(rig);return rig;
 }
 static Rig ReadNif(string path){var n=NifHierarchyReader.Read(path);return new(){Name=n.FirstOrDefault(x=>x.Parent<0)?.Name??"NIF",Names=n.Select(x=>x.Name).ToArray(),Parents=n.Select(x=>checked((short)x.Parent)).ToArray(),Reference=n.Select(x=>new Pose(x.Translation,x.Rotation,x.Scale)).ToArray(),SourceFormat="NIF",SkeletonOnly=true};}
 public static void Validate(Rig r){int n=r.Names.Length;if(n is <1 or >MaxBones||r.Parents.Length!=n||r.Reference.Length!=n||string.IsNullOrWhiteSpace(r.Name)||r.Name.Length>512||r.FloatSlots.Length>4096)throw new InvalidDataException(UiText.T("skeletonInvalid"));var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<n;i++){var p=r.Reference[i];if(string.IsNullOrWhiteSpace(r.Names[i])||r.Names[i].Length>512||r.Names[i].Any(char.IsControl)||!names.Add(r.Names[i])||r.Parents[i]<-1||r.Parents[i]>=n||r.Parents[i]==i||!Finite(p.T)||!Finite(p.S)||!float.IsFinite(p.R.X)||!float.IsFinite(p.R.Y)||!float.IsFinite(p.R.Z)||!float.IsFinite(p.R.W)||Math.Abs(p.R.LengthSquared()-1)>.01||p.T.Length()>1000000||Math.Max(Math.Abs(p.S.X),Math.Max(Math.Abs(p.S.Y),Math.Abs(p.S.Z)))>1000||Math.Min(Math.Abs(p.S.X),Math.Min(Math.Abs(p.S.Y),Math.Abs(p.S.Z)))<.000001)throw new InvalidDataException(UiText.T("skeletonInvalid")+" / "+i);r.Reference[i]=p with{R=Quaternion.Normalize(p.R)};}
  var state=new byte[n];var order=new List<int>();void Visit(int i,int depth){if(depth>256)throw new InvalidDataException(UiText.T("skeletonCycle"));if(state[i]==1)throw new InvalidDataException(UiText.T("skeletonCycle"));if(state[i]==2)return;state[i]=1;if(r.Parents[i]>=0)Visit(r.Parents[i],depth+1);state[i]=2;order.Add(i);}for(int i=0;i<n;i++)Visit(i,0);r.EvaluationOrder=order.ToArray();
 }
 static bool Finite(Vector3 v)=>float.IsFinite(v.X)&&float.IsFinite(v.Y)&&float.IsFinite(v.Z);
 public static Rig Select(IReadOnlyList<Rig> candidates,ISet<Rig>? preferred=null,ISet<Rig>? ragdoll=null){var valid=candidates.Where(c=>!c.Name.Contains("ragdoll",StringComparison.OrdinalIgnoreCase)&&ragdoll?.Contains(c)!=true).ToArray();if(valid.Length>1&&preferred!=null){var linked=valid.Where(c=>preferred.Contains(c)).ToArray();if(linked.Length==1)return linked[0];}if(valid.Length!=1)throw new InvalidDataException(UiText.T("skeletonAmbiguous"));return valid[0];}
 public static Rig ReadXml(byte[] bytes){using var stream=new MemoryStream(bytes);using var reader=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=MaxBytes,MaxCharactersFromEntities=0});var doc=XDocument.Load(reader);var root=doc.Root;if(root?.Name!="hkpackfile"||root.Attribute("classversion")?.Value!="8"||root.Attribute("contentsversion")?.Value!="hk_2010.2.0-r1")throw new InvalidDataException(UiText.T("skeletonXml"));var objects=root.Elements("hksection").Where(x=>x.Attribute("name")?.Value=="__data__").SelectMany(x=>x.Elements("hkobject")).ToArray();if(objects.Length>16384)throw new InvalidDataException(UiText.T("skeletonSize"));var rigs=new List<Rig>();var ids=new Dictionary<string,Rig>();foreach(var o in objects.Where(x=>x.Attribute("class")?.Value=="hkaSkeleton")){string Param(string name)=>One(o,name).Value;var b=One(o,"bones");var p=One(o,"parentIndices");var pose=One(o,"referencePose");int count=Count(b);var names=b.Elements("hkobject").Select(n=>One(n,"name").Value).ToArray();if(count!=names.Length||Count(p)!=count||Count(pose)!=count)throw new InvalidDataException(UiText.T("skeletonInvalid"));short[] parents=Tokens(p.Value).Select(x=>short.Parse(x,System.Globalization.CultureInfo.InvariantCulture)).ToArray();var groups=Regex.Matches(pose.Value,@"\(([^()]*)\)",RegexOptions.CultureInvariant,TimeSpan.FromSeconds(1));if(groups.Count!=count*3||Regex.Replace(pose.Value,@"\([^()]*\)","",RegexOptions.CultureInvariant,TimeSpan.FromSeconds(1)).Any(c=>!char.IsWhiteSpace(c)))throw new InvalidDataException(UiText.T("skeletonXml"));var poses=new Pose[count];for(int i=0;i<count;i++){float[] Vec(int index,int length){var a=Tokens(groups[index].Groups[1].Value).Select(Number).ToArray();if(a.Length!=length)throw new InvalidDataException(UiText.T("skeletonXml"));return a;}var t=Vec(i*3,3);var q=Vec(i*3+1,4);var s=Vec(i*3+2,3);poses[i]=new(new(t[0],t[1],t[2]),new(q[0],q[1],q[2],q[3]),new(s[0],s[1],s[2]));}var r=new Rig{Name=Param("name"),Names=names,Parents=parents,Reference=poses,SourceFormat="Havok XML",SkeletonOnly=true};var slots=o.Elements("hkparam").SingleOrDefault(x=>x.Attribute("name")?.Value=="floatSlots");if(slots!=null){r.FloatSlots=slots.Elements("hkcstring").Select(x=>x.Value).ToArray();if(Count(slots)!=r.FloatSlots.Length)throw new InvalidDataException(UiText.T("skeletonXml"));}rigs.Add(r);if(o.Attribute("name") is {} id&&!ids.TryAdd(id.Value,r))throw new InvalidDataException(UiText.T("skeletonInvalid"));}
 var preferred=new HashSet<Rig>();var ragdoll=new HashSet<Rig>();foreach(var o in objects){string? cls=o.Attribute("class")?.Value;string param=cls=="hkaAnimationContainer"?"skeletons":"skeleton";if(cls is not ("hkaAnimationContainer" or "hkaRagdollInstance"))continue;foreach(string id in Tokens(One(o,param).Value))if(ids.TryGetValue(id,out var name))(cls=="hkaAnimationContainer"?preferred:ragdoll).Add(name);}return Select(rigs,preferred,ragdoll);
 }
 static XElement One(XElement e,string name){var a=e.Elements("hkparam").Where(x=>x.Attribute("name")?.Value==name).ToArray();return a.Length==1?a[0]:throw new InvalidDataException(UiText.T("skeletonXml")+" / "+name);}
 static int Count(XElement e)=>int.TryParse(e.Attribute("numelements")?.Value,out int count)&&count>=0&&count<=MaxBones?count:throw new InvalidDataException(UiText.T("skeletonInvalid"));
 static string[] Tokens(string s)=>s.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries);
 static float Number(string s)=>float.Parse(s,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture);
 public static Rig ReadJson(byte[] bytes){using var json=JsonDocument.Parse(bytes,new JsonDocumentOptions{MaxDepth=24});var j=json.RootElement;void Shape(JsonElement e,params string[] fields){if(e.ValueKind!=JsonValueKind.Object)throw new InvalidDataException(UiText.T("skeletonJson"));var seen=new HashSet<string>();foreach(var p in e.EnumerateObject())if(!fields.Contains(p.Name)||!seen.Add(p.Name))throw new InvalidDataException(UiText.T("skeletonJson")+" / "+p.Name);if(fields.Any(f=>!seen.Contains(f)))throw new InvalidDataException(UiText.T("skeletonJson"));}Shape(j,"schemaVersion","skeletonName","coordinateSystem","bones");if(j.GetProperty("schemaVersion").GetInt32()!=1||j.GetProperty("coordinateSystem").GetString()!="skyrim-z-up-xyzw")throw new InvalidDataException(UiText.T("skeletonJson"));var bones=j.GetProperty("bones");if(bones.ValueKind!=JsonValueKind.Array||bones.GetArrayLength() is <1 or >MaxBones)throw new InvalidDataException(UiText.T("skeletonInvalid"));var names=new List<string>();var parents=new List<short>();var poses=new List<Pose>();foreach(var b in bones.EnumerateArray()){Shape(b,"boneName","parentIndex","localTranslation","localRotation","localScale");float[] V(string name,int count){var v=b.GetProperty(name);if(v.ValueKind!=JsonValueKind.Array||v.GetArrayLength()!=count)throw new InvalidDataException(UiText.T("skeletonJson"));return v.EnumerateArray().Select(x=>x.GetSingle()).ToArray();}var t=V("localTranslation",3);var q=V("localRotation",4);var s=V("localScale",3);names.Add(b.GetProperty("boneName").GetString()??"");parents.Add(b.GetProperty("parentIndex").GetInt16());poses.Add(new(new(t[0],t[1],t[2]),new(q[0],q[1],q[2],q[3]),new(s[0],s[1],s[2])));}return new(){Name=j.GetProperty("skeletonName").GetString()??"",Names=names.ToArray(),Parents=parents.ToArray(),Reference=poses.ToArray(),SourceFormat="JSON v1",SkeletonOnly=true};}
}
